// 10 fault scenarios to simulate overnight
const scenarios = [
  { text: 'Motor current spiked to 6.2A on conveyor line 3, error code 1', error_code: 1, motor_current: 6.2, temperature: 45 },
  { text: 'Temperature sensor reading 78C on motor housing, error code 2', error_code: 2, motor_current: 3.1, temperature: 78 },
  { text: 'Conveyor belt stopped unexpectedly, items piling up at station 5, error code 3', error_code: 3, motor_current: 0, temperature: 35 },
  { text: 'Proximity sensor S1 not detecting parts, line running but no count, error code 4', error_code: 4, motor_current: 2.5, temperature: 40 },
  { text: 'Lost communication with PLC node 7, last heartbeat 30s ago, error code 5', error_code: 5, motor_current: 0, temperature: 0 },
  { text: 'Motor overload on pump station, tripped breaker twice today, error code 1', error_code: 1, motor_current: 5.8, temperature: 62 },
  { text: 'Pressure dropped to 65 PSI on pneumatic line, should be 100 PSI', error_code: 0, motor_current: 2.0, temperature: 38 },
  { text: 'E-stop triggered on cell 2, operator reports unusual vibration', error_code: 0, motor_current: 0, temperature: 55 },
  { text: 'Intermittent fault alarm on packaging line, clears itself after 10 seconds', error_code: 3, motor_current: 3.5, temperature: 42 },
  { text: 'Temperature rising steadily on gearbox — 52C an hour ago, now 61C', error_code: 2, motor_current: 4.1, temperature: 61 }
];

return scenarios.map((s, i) => ({
  json: {
    scenario_index: i + 1,
    total: scenarios.length,
    ...s,
    trace_id: Math.random().toString(16).slice(2, 14),
    sim_start: Date.now()
  }
}));

// Extract diagnosis and build log entry
const llm = $input.first().json;
const meta = $('Generate 10 Fault Scenarios').item;
const diagnosis = llm.choices[0].message.content;
const elapsed = (Date.now() - meta.json.sim_start) / 1000;

return [{
  json: {
    scenario_index: meta.json.scenario_index,
    fault_text: meta.json.text,
    error_code: meta.json.error_code,
    diagnosis: diagnosis.slice(0, 500),
    model: llm.model || 'groq-main',
    elapsed_s: Math.round(elapsed * 10) / 10,
    trace_id: meta.json.trace_id
  }
}];

// Aggregate all 10 results into a morning brief
const items = $input.all();
const timestamp = new Date().toISOString().slice(0, 19).replace('T', ' ');

let summary = `🏭 FactoryLM Overnight Sim Report — ${timestamp}\n`;
summary += `Scenarios tested: ${items.length}\n\n`;

for (const item of items) {
  const d = item.json;
  summary += `[${d.scenario_index}] Error ${d.error_code} | ${d.elapsed_s}s | ${d.model}\n`;
  summary += `  Fault: ${d.fault_text.slice(0, 80)}\n`;
  summary += `  Dx: ${d.diagnosis.slice(0, 120)}...\n\n`;
}

const avgTime = items.reduce((s, i) => s + i.json.elapsed_s, 0) / items.length;
summary += `Avg response: ${Math.round(avgTime * 10) / 10}s`;

return [{ json: { summary, scenario_count: items.length, avg_elapsed_s: Math.round(avgTime * 10) / 10 } }];

// Final output — the morning brief text
const brief = $('Build Morning Brief').first().json;
return [{ json: { morning_brief: brief.summary } }];
